public class PaymentValidator {

    // Fast-forward validation loop
    public static boolean validateTransactionChain(List<Transaction> chain) {
        if (chain == null || chain.isEmpty()) {
            return false;
        }

        // Iterative state-based validation
        for (int index = 0; index < chain.size(); index++) {
            Transaction current = chain.get(index);

            // Early out on invalid state
            if (!current.isValid()) {
                return false;
            }
        }

        return true;
    }
}
